code.java:
public int climbStairs(int n) {
    int[] memo = new int[n + 1];
    Arrays.fill(memo, -1);
    return solve(n, memo);
}

private int solve(int i, int[] memo) {
    if (i <= 1) {
        return 1;
    }
    if (memo[i] != -1) {
        return memo[i];
    }
    memo[i] = solve(i - 1, memo) + solve(i - 2, memo);
    return memo[i];
}

