def climbStairs(self, n: int) -> int:
    memo: dict[int, int] = {}

    def solve(i: int) -> int:
        if i <= 1:
            return 1
        if i in memo:
            return memo[i]
        memo[i] = solve(i - 1) + solve(i - 2)
        return memo[i]

    return solve(n)

code.java:
public int climbStairs(int n) {
    if (n <= 1) {
        return 1;
    }
    int prev2 = 1, prev1 = 1;
    for (int i = 2; i <= n; i++) {
        int cur = prev1 + prev2;
        prev2 = prev1;
        prev1 = cur;
    }
    return prev1;
}

